import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../Styles/UserProfile.css"; // نفس تنسيق الطالب

const CompanyProfile = () => {
  const navigate = useNavigate();

  const [company, setCompany] = useState({});
  const [preview, setPreview] = useState(null);
  const [showBankModal, setShowBankModal] = useState(false);

  const [payment, setPayment] = useState({
    accountHolder: "",
    bankName: "",
    accountNumber: "",
    iban: "",
  });

  // Load company
  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));
    if (!saved?.email) {
      navigate("/login");
      return;
    }

    axios
      .get(`http://localhost:3001/company/${saved.email}`)
      .then((res) => {
        setCompany(res.data);
        setPayment(res.data.bankInfo || {});
      })
      .catch(() => alert("Failed to load company"));
  }, [navigate]);

  // Upload Company License
  const handleUploadLicense = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const form = new FormData();
    form.append("file", file);
    form.append("email", company.email);
    form.append("type", "license");

    try {
      const res = await axios.post(
        "http://localhost:3001/uploadCompanyFile",
        form,
        {
          headers: { "Content-Type": "multipart/form-data" },
        }
      );

      setCompany((prev) => ({ ...prev, licenseFile: res.data.fileUrl }));
      alert("License uploaded successfully!");
    } catch {
      alert("Failed to upload license");
    }
  };

  // Delete license
  const handleDeleteLicense = async () => {
    if (!window.confirm("Delete company license?")) return;

    try {
      await axios.put("http://localhost:3001/uploadCompanyFile", {
        email: company.email,
        type: "license",
        file: "",
      });

      setCompany((prev) => ({ ...prev, licenseFile: null }));
    } catch {
      alert("Delete failed");
    }
  };

  // Save Bank Info
  const saveBank = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`http://localhost:3001/company/${company.email}/bank`, {
        ...payment,
      });

      alert("Bank details saved!");
      setShowBankModal(false);
    } catch {
      alert("Failed to save bank details");
    }
  };

  // Delete Bank Info
  const deleteBankInfo = async () => {
    if (!window.confirm("Delete bank info?")) return;

    try {
      await axios.post(`http://localhost:3001/company/${company.email}/bank`, {
        accountHolder: "",
        bankName: "",
        accountNumber: "",
        iban: "",
      });

      setPayment({
        accountHolder: "",
        bankName: "",
        accountNumber: "",
        iban: "",
      });

      alert("Bank info deleted");
    } catch {
      alert("Failed to delete bank info");
    }
  };

  return (
    <div className="profile-page">
      {/* PROFILE CARD */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-img-container">
            <img
              src={
                preview ||
                company.profileImage ||
                "https://cdn-icons-png.flaticon.com/512/3135/3135768.png"
              }
              className="profile-img"
              alt=""
            />
          </div>

          <div>
            <h2 className="profile-name">{company.companyName}</h2>
            <p className="profile-email">{company.email}</p>
            <p className="profile-detail">
              {company.industry} • {company.location}
            </p>
          </div>
        </div>
      </div>

      {/* COMPANY INFO */}
      <div className="payment-box">
        <h3>Company Information</h3>

        <p>
          <strong>Industry:</strong> {company.industry}
        </p>
        <p>
          <strong>Location:</strong> {company.location}
        </p>
        <p>
          <strong>Founded:</strong> {company.foundedDate || "—"}
        </p>
        <p>
          <strong>Status:</strong> <span className="status active">Active</span>
        </p>
      </div>

      {/* LICENSE FILE */}
      <div className="payment-box">
        <h3>Company License</h3>

        {company.licenseFile ? (
          <div className="cv-section">
            <p className="cv-success">License Uploaded Successfully</p>

            <div className="cv-actions">
              <a
                href={company.licenseFile}
                target="_blank"
                className="cv-btn view"
              >
                View
              </a>

              <input
                id="licenseUpload"
                type="file"
                accept=".pdf"
                style={{ display: "none" }}
                onChange={handleUploadLicense}
              />
              <label className="cv-btn replace" htmlFor="licenseUpload">
                Replace
              </label>

              <button className="cv-btn delete" onClick={handleDeleteLicense}>
                Delete
              </button>
            </div>
          </div>
        ) : (
          <>
            <input
              id="licenseUpload"
              type="file"
              accept=".pdf"
              style={{ display: "none" }}
              onChange={handleUploadLicense}
            />
            <label className="upload-cv-btn" htmlFor="licenseUpload">
              Upload License (PDF)
            </label>
          </>
        )}
      </div>

      {/* BANK INFO */}
      <div className="payment-box">
        <h3>Bank Information</h3>

        {payment.bankName ? (
          <>
            <p>
              <strong>Account Holder:</strong> {payment.accountHolder}
            </p>
            <p>
              <strong>Bank Name:</strong> {payment.bankName}
            </p>
            <p>
              <strong>Account Number:</strong> {payment.accountNumber}
            </p>
            <p>
              <strong>IBAN:</strong> {payment.iban}
            </p>

            <div className="card-buttons">
              <button
                className="edit-card-btn"
                onClick={() => setShowBankModal(true)}
              >
                Edit
              </button>

              <button className="delete-card-btn" onClick={deleteBankInfo}>
                Delete
              </button>
            </div>
          </>
        ) : (
          <button
            className="add-card-btn"
            onClick={() => setShowBankModal(true)}
          >
            + Add Bank Info
          </button>
        )}
      </div>

      {/* MODAL */}
      {showBankModal && (
        <div className="modal-overlay">
          <div className="modal-box">
            <div className="modal-header">
              <h3>Edit Bank Information</h3>
              <button
                className="close-btn"
                onClick={() => setShowBankModal(false)}
              >
                ×
              </button>
            </div>

            <form onSubmit={saveBank}>
              <label>Account Holder</label>
              <input
                className="modal-input"
                value={payment.accountHolder || ""}
                onChange={(e) =>
                  setPayment({ ...payment, accountHolder: e.target.value })
                }
              />

              <label>Bank Name</label>
              <input
                className="modal-input"
                value={payment.bankName || ""}
                onChange={(e) =>
                  setPayment({ ...payment, bankName: e.target.value })
                }
              />

              <label>Account Number</label>
              <input
                className="modal-input"
                value={payment.accountNumber || ""}
                onChange={(e) =>
                  setPayment({ ...payment, accountNumber: e.target.value })
                }
              />

              <label>IBAN</label>
              <input
                className="modal-input"
                value={payment.iban || ""}
                onChange={(e) =>
                  setPayment({ ...payment, iban: e.target.value })
                }
              />

              <div className="modal-buttons">
                <button className="save-btn" type="submit">
                  Save
                </button>
                <button
                  className="clear-btn"
                  type="button"
                  onClick={() => setShowBankModal(false)}
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyProfile;
